query GetDynamicTeaser($configuration: String!, $collectionId: String!, $input: RecommendationInput!) {
  cluster(
    configuration: $configuration
    collectionId: $collectionId
    input: $input
  ) {
    items {
      ... on ISmartCollection {
        ...ISmartCollectionTeaserData
        teaser {
          description
          imageWithoutLogo {
            altText
            layouts {
              ...StageImageSizes
            }
          }
        }
        logo {
          altText
        }
        infoText
        logoLeft {
          ...LogoImageFragment
        }
        contentOwner {
          ...ContentOwner
        }
        publicationFrequency
        structuralMetadata {
          ...ISmartCollectionStructuralMetaData
        }
        heroTrailers: trailers(first: 1, sortBy: {field: HERO_TRAILER, direction: DESC}) {
          nodes {
            ...BackgroundVideo
          }
        }
      }
      ... on MetaCollection {
        ...MetaCollectionTeaserData
        teaser {
          description
          imageWithoutLogo {
            altText
            layouts {
              ...StageImageSizes
            }
          }
        }
        logo {
          altText
        }
        logoLeft {
          ...LogoImageFragment
        }
        contentOwners {
          nodes {
            ...ContentOwner
          }
        }
      }
      ... on Video {
        ...VideoTeaserData
        teaser {
          description
          imageWithoutLogo {
            altText
            layouts {
              ...StageImageSizes
            }
          }
        }
        contentOwner {
          ...ContentOwner
        }
        availability {
          vod {
            visibleFrom
          }
        }
        structuralMetadata {
          ...VideoStructuralMetaData
        }
        smartCollection {
          logo {
            altText
          }
          logoLeft {
            ...LogoImageFragment
          }
        }
      }
    }
  }
  ...ResponseMetadataFragment
